const cp = require('child_process');
const path = require('path');
if (!global.neurolinkServer) {
    const batPath = path.join('C:', 'Codes', 'audiobook', 'start_neurolink_server.bat');
    // 使用 cmd.exe /c start "" "batPath" 强制弹出一个独立的可见 CMD 窗口
    global.neurolinkServer = cp.spawn('cmd.exe', ['/c', 'start', '""', batPath], {
        env: Object.assign({}, process.env, { LAUNCHED_BY_KOODO: '1' }),
        windowsHide: false,
        detached: true
    });
    // 当 Koodo 关闭时，根据窗口标题杀掉该窗口以及其下的所有子进程 (python server)
    process.on('exit', () => {
        try { cp.execSync('taskkill /FI "WINDOWTITLE eq Neurolink TTS Server*" /T /F'); } catch(e){}
    });
}

const getAudioPath = async(t, e, a, o) => {
    let i = require("path");
    let n = require("fs");
    let r = new Date().getTime() + "." + o.voiceFormat;
    let ttsDir = i.join(a, "tts");
    let filePath = i.join(ttsDir, r);

    if (!n.existsSync(ttsDir)) {
        n.mkdirSync(ttsDir);
    }

    let audioData = await getTTSAudio(t, e, o);
    if (!audioData) return "";

    n.writeFileSync(filePath, audioData);
    return filePath;
};

const getTTSAudio = async(t, e, a) => {
    let o = a.url || "http://127.0.0.1:8000/koodo_tts",
        i = a.text_language || "zh",
        n = a.prompt_language || "zh",
        r_path = a.refer_wav_path || "",
        g = a.prompt_text || "zh",
        s = a.cut_punc || "，。",
        u = require("axios");

    let maxRetries = 30; // 最多尝试30次
    let delayMs = 2000;  // 每次等待2秒

    while (maxRetries > 0) {
        try {
            let res = await u.post(o, { refer_wav_path: r_path, prompt_text: g, prompt_language: n, text: t, text_language: i, cut_punc: s }, { responseType: "arraybuffer" });
            return res.data;
        } catch (err) {
            console.log("TTS Server not ready, retrying... tries left: " + maxRetries);
            maxRetries--;
            if (maxRetries === 0) {
                console.log("Failed to connect to TTS server after maximum retries.");
                return "";
            }
            await new Promise(resolve => setTimeout(resolve, delayMs));
        }
    }
};
global.getAudioPath = getAudioPath;
